def draft():
    rows=[]
    for n,title,body,sources,objections in TASKS:
        row=dict(task=n,title=title,draft=body,sources=sources.split(','),objections=objections)
        rows.append(row)
        path=ROOT/'notes'/f'task_{n:02d}.md'
        if not path.exists():
            path.write_text(f'# Task {n:02d}: {title}\n\n## Initial evidence-backed draft\n\n{body}\n\nSource IDs: {sources}.\n\n## Initial attack\n\n'+'\n'.join(f'{i+1}. {x}' for i,x in enumerate(objections))+'\n\nVerification rounds and repaired results will be appended after the model runs.\n',encoding='utf-8')
    (ROOT/'data/research_tasks.json').write_text(json.dumps(rows,indent=2),encoding='utf-8')
    print('Created twenty distinct task drafts and attacks.')
if __name__=='__main__': draft()
